    h, w = len(grid), len(grid[0])
    clues = {}
    for r, row in enumerate(grid):
        nonzero = {v for v in row if v != 0}
        if nonzero:
            if len(nonzero) != 1:
                raise ValueError("each clue row must contain one color")
            clues[r] = next(iter(nonzero))
    period = len(clues)
    if not period:
        raise ValueError("no clue rows")
    by_residue = {}
    for r, color in clues.items():
        residue = r % period
        if residue in by_residue and by_residue[residue] != color:
            raise ValueError("conflicting clue rows for residue")
        by_residue[residue] = color
    if len(by_residue) != period:
        raise ValueError("clues do not cover every row residue")
    return [[by_residue[r % period] for _ in range(w)] for r in range(h)]


